    515: { description: 'Сфотографировала ли камера Панора (Shuttah) Ральзея.', values: BOOL },
    520: { description: 'Сколько Бубиннов (Rudinn) побито за главу. obj_diamondenemy_Draw при поражении врага (monster==0) делает global.flag[520] += 1 (и при flag[51+myself]==5 ещё flag[523] += 1). scr_text использует normal_kills = global.flag[520] - global.flag[523] для корректировки счётчика жестокости flag[40]. obj_npc_room_Other_10 при flag[520]==0 выдаёт особую реплику.', min: 0 },
    521: { description: 'Сколько Червонн (Hathy) побито за главу. obj_heartenemy_Draw при поражении врага (monster==0) делает global.flag[521] += 1 (и при flag[51+myself]==5 ещё flag[524] += 1). obj_npc_room_Other_10 выбирает реплики по flag[521] (<=2, >0) и считает normal_kills = global.flag[521] - global.flag[524] для корректировки flag[40].', min: 0 },
    522: { description: 'Побита ли Крестя (Clover). obj_clubsenemy_Draw при поражении врага (monster==0) делает global.flag[522] += 1. obj_npc_room_Other_10 (Гл.1/2/3/4) при flag[522]==1 заменяет дружелюбные реплики Кресте на обиженные («Were you invited?... You DID hurt us...»).', values: { 0: 'Не побита', 1: 'Побита' }, min: 0 },
    523: { description: 'Сколько Бубиннов (Rudinn) побито одиночным ударом Сьюзи. obj_diamondenemy_Draw при monster==0 && flag[51+myself]==5 делает global.flag[523] += 1 (одновременно с flag[520]). scr_text при прощении вычитает: global.flag[43] -= global.flag[523], затем normal_kills = global.flag[520] - global.flag[523].', min: 0 },
    524: { description: 'Сколько Червонн (Hathy) побито одиночным ударом Сьюзи. obj_heartenemy_Draw при monster==0 && flag[51+myself]==5 делает global.flag[524] += 1 (одновременно с flag[521]). obj_npc_room_Other_10 при прощении вычитает global.flag[43] -= global.flag[524], затем normal_kills = global.flag[521] - global.flag[524].', min: 0 },
    526: { description: 'Состояние первого боя-поединка с Tasque в кибермире (room_dw_cyber_tasque_battle, бокс-механика o_boxingcontroller). По global.flag[526] меняется снижение урона за ход: <5 — порог 60, >=5 && <7 — порог 40, >=7 — порог 30. o_boxingcontroller_Other_13 при flag[526]<10 делает global.flag[526]++ (растёт по ходу боя, максимум 10). obj_queenscreen в этой комнате при flag[526]!=0 ставит image_index=11. encounterflag для комнаты = 526.', min: 0 },
    527: { description: 'Состоялась ли первая встреча с Virovirokun.', values: BOOL },
    528: { description: 'Состоялась ли вторая встреча со Smorgasbord (room_dw_cyber_maze_queenscreen). obj_controller_dw_cyber_maze_queenscreen_Step при global.entrance==2 || flag[528]==1 ставит spawn7=true (спавн врага). obj_chaseenemy в этой комнате задаёт encounterflag = 528.', values: { 0: 'Нет', 1: 'Да' } },
    529: { description: 'Исход первого боя с Птицыном/Berdly (Гл.2, спецбой). obj_berdly_encounter_setup задаёт global.specialbattle=3, encounterno=58, encounterflag=529, global.flag[54]=encounterflag. obj_queen_enemy_Step учитывает flag[529] в проверке особой сцены поражения Королевы: defeat_cutscene_version = (flag[529]==2||3) && (flag[550]==2||3) && (flag[548]==2||3).', values: { 0: 'Бой не пройден', 1: 'Побеждён силой', 2: 'Пощажён', 3: 'Усмирён (через ДЕЙСТВИЕ)', 6: 'Заморожен (лёд Ноэль)' } },
    531: { description: 'Обучающая встреча с Virovirokun (room_dw_city_big_1). obj_ch2_tutorialViroMaker создаёт виро с encounterflag=531, если flag[531] ещё не 0 и не 6 (и есть Ноэль). obj_chaseenemy в комнате для extflag=="tutViro" ставит encounterflag=531. obj_weirdroute_manipulator_Step: при flag[915]==0 && flag[531]==6 ставит global.flag[915]=1 (продвижение странного маршрута, snd_ominous).', values: { 0: 'Не пройдена', 6: 'Пройдена' } },
    532: { description: 'Встреча «Ambulance» (жестокий/странный маршрут). obj_chaseenemy для extflag=="rightOma"/"leftOma" задаёт encounterflag=532. obj_weirdroute_manipulator_Step при flag[915]==1.75 && flag[916]==0 проверяет flag[564]==6 && flag[565]==6 && flag[532]==6 && flag[533]==6 и при выполнении ставит flag[915]=2 (snd_ominous).', values: { 0: 'Не пройдена', 6: 'Пройдена' } },
    533: { description: 'Встреча «Antivirus» (жестокий/странный маршрут, room_dw_city_big_2). obj_chaseenemy в комнате задаёт encounterflag=533. obj_weirdroute_manipulator_Step при flag[915]==1.75 && flag[916]==0 проверяет flag[564]==6 && flag[565]==6 && flag[532]==6 && flag[533]==6 и при выполнении ставит flag[915]=2.', values: { 0: 'Не пройдена', 6: 'Пройдена' } },
    539: { description: 'Исход боя с Задатьщей (Tasque) в кибер-лабиринте (room_dw_cyber_maze_tasque). obj_dw_cyber_maze_tasque_controller при flag[539]!=0 ставит экранам image_index=11; при flag[539]==2||3 спавнит преследователей (obj_chaseenemy). obj_queenscreen в комнате при flag[539]!=0 ставит image_index=11. obj_chaseenemy задаёт encounterflag=539.', values: { 0: 'Бой не пройден', 1: 'Побеждена силой', 2: 'Пощажена', 3: 'Усмирена (через ДЕЙСТВИЕ)', 6: 'Заморожена (лёд Ноэль)' } },
    540: { description: 'Первая встреча с дворецкими (Butlers) — room_dw_mansion_single_pot. obj_chaseenemy задаёт encounterflag=540. obj_controller_dw_mansion_single_pot при flag[540]==6 спавнит преследователя (obj_chaseenemy).', values: { 0: 'Не было', 6: 'Пройдена (появляется преследователь)' } },
    541: { description: 'Встреча с группой дворецких (Butlers) — room_dw_mansion_potBalance. obj_chaseenemy задаёт encounterflag=541. obj_controller_dw_mansion_potBalance при flag[541]!=0 ставит global.flag[385]=1. scr_encountersetup (case 56) при flag[541]==0 задаёт flag[426]=-1.', min: 0 },
    542: { description: 'Встреча с Менеджером задач (Task Manager) — room_dw_mansion_east_2f_d. obj_npc_tasquemanager_Step при con==3 ставит encounterflag=542, global.flag[54]=encounterflag, global.flag[9]=2 и запускает scr_battle(57,...). obj_controller_tasquePaintingsRevisit при flag[542]!=0 спавнит swatch (obj_chaseenemy). obj_weirdroute_manipulator_Create при flag[542]==0 создаёт врага.', min: 0 },
    544: { description: 'Побег от дворецких (Butlers).', min: 0 },
