    550: { description: 'Исход второй стычки с Птицыном (Berdly) в Кибер-городе (Гл.2). obj_ch2_city_berdly_Step задаёт музыку berdly_chase.ogg, encounterflag=550, global.flag[54]=encounterflag, scr_battle(82,1,...), global.flag[9]=1. obj_queen_enemy_Step учитывает (flag[550]==2||3) в проверке особой сцены поражения Королевы.', values: { 2: 'Пройдена (вариант 2 — пощада)', 3: 'Пройдена (вариант 3 — усмирение)' }, min: 0, category: 'ch2' },
    559: { description: 'Встреча «Trash Popup» на свалке (жестокий маршрут). obj_overworld_poppup_Create при global.plot<100 задаёт spr_poppup_peeking, encounterflag=559 (и при flag[916]!=0 уничтожается). obj_weirdroute_manipulator_Step при flag[915]==1 && flag[916]==0 проверяет flag[559]==6 && flag[560]==6 && flag[561]==6 и ставит flag[915]=1.5.', values: { 0: 'Не пройдена', 6: 'Пройдена' } },
